,p_translate_from_id=>wwv_flow_imp.id(20498160790640898541)
,p_translate_column_id=>21
,p_translate_to_lang_code=>'nl'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P1000_ID,P1000_USR_ID'', p_values => ID||'',''||USR_ID) LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P1000_ID,''0'') = "ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("COMPANY_NAME", 1, 50)||( case when length("COMPANY_NAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'     ''Audits: '' || nvl((select count(1) from icca_audits where cnt_id = x.id), 0)  LIST_TEXT,',
'    null LIST_BADGE',
'from "ICCA_CLIENTS" x',
'where (:P1000_SEARCH is null',
'        or upper(x."COMPANY_NAME") like ''%''||upper(:P1000_SEARCH)||''%''',
'        or upper(x."CONTACT_PERSON") like ''%''||upper(:P1000_SEARCH)||''%''',
'    )',
'and x.usr_id not in (select id from icca_users where deleted = ''Y'')',
'order by x.created_date, x.modified_date, company_name'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P1000_ID,P1000_USR_ID'', p_values => ID||'',''||USR_ID) LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
