,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with w_data as (',
'    select  aop_data',
'    ,       doc_ids',
'    from icca_aop_report_data_vw',
'    where adt_id = :P3065_ADT_ID',
')',
', w_all as(',
'    select  aop_data',
'    ,       doc_ids',
'    from    w_data',
'    /*',
'        Fallback query so report does not throw an AOP error, report will instead be empty',
'        COMMENTING OUT AS IT DOESNT WORK, FOR WHATEVER REASON',
'    */',
'    -- union all',
'    -- select  to_clob(''',
'    -- [',
'    --     {',
'    --         "filename": "rapport",',
'    --         "data": []',
'    --     }',
'    -- ]'') aop_data',
'    -- ,       null doc_ids',
'    -- from    dual',
'    -- where   not exists(',
'    --     select  1',
'    --     from    w_data-- ',
'    -- )',
')',
'/*',
'   Performance issues if BLOBS directly in view since would need to convert every image to base64 as well',
'   This is probably faster',
'*/',
'select  case when doc_ids is not null then json_transform (',
'                aop_data',
'            ,   set ''$.data[0].htmlContent'' =  icca_aop_pdf.f_get_imgs_html(doc_ids)',
'                returning clob',
'        ) else aop_data end as aop_data',
'from    w_all',
';',
''))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
