,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT c.company_name, COUNT(a.id) AS total_audits',
'FROM icca_audits a',
'JOIN icca_clients c ON a.cnt_id = c.id',
'WHERE cnt_id in (',
'    select  cnt.id',
'    from    icca_clients cnt',
'    join    icca_pfr_clients pnt on cnt.id = pnt.cnt_id',
'    join    icca_performers pfr on pfr.id = pnt.pfr_id',
'    and     (',
'              (:F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'              and 1=1)',
'            or',
'            (:F_UGP_SYSTEEM_NAAM in (''UGP_PERFORMERS'')',
'            and pfr.usr_id = :F_GBR_ID',
'            )',
'            or',
'            (:F_UGP_SYSTEEM_NAAM in (''UGP_CLIENTS'')',
'            and cnt.usr_id = :F_GBR_ID',
'            )',
'        )',
')',
'GROUP BY c.company_name',
'ORDER BY total_audits DESC;',
''))
,p_series_type=>'bar'
,p_items_value_column_name=>'TOTAL_AUDITS'
,p_items_label_column_name=>'COMPANY_NAME'
