wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(20498884931419341645)
,p_chart_id=>wwv_flow_imp.id(20498884894298341644)
,p_static_id=>'new'
,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  cnt.company_name label',
',       count(1) count',
'from    icca_client_locations cln',
'join    icca_clients          cnt on cnt.id = cln.cnt_id',
'WHERE cnt_id in (',
'    select  cnt.id',
'    from    icca_clients cnt',
'    join    icca_pfr_clients pnt on cnt.id = pnt.cnt_id',
'    join    icca_performers pfr on pfr.id = pnt.pfr_id',
'    and     (',
'              (:F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'              and 1=1)',
'            or',
'            (:F_UGP_SYSTEEM_NAAM in (''UGP_PERFORMERS'')',
'            and pfr.usr_id = :F_GBR_ID',
'            )',
'            or',
'            (:F_UGP_SYSTEEM_NAAM in (''UGP_CLIENTS'')',
'            and cnt.usr_id = :F_GBR_ID',
'            )',
'        )',
')',
'group by cnt.company_name  '))
,p_series_type=>'area'
,p_items_value_column_name=>'COUNT'
,p_items_label_column_name=>'LABEL'
,p_line_type=>'auto'
,p_marker_rendered=>'auto'
,p_marker_shape=>'auto'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
);
