,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  adt.id',
',       adt.pfr_id',
',       adt.code',
',       adt.audit_date',
',       adt.last_control_date',
',       adt.active',
',       adt.activate',
',       adt.audit_completed',
',       adt.cnt_id',
',       adt.cln_id',
',       adt.type',
',       adt.created_date',
',       adt.created_by',
',       adt.modified_date',
',       adt.modified_by',
',       nvl2(cnt.audit_report_type, cnt.audit_report_type || ''_TEMPLATE.docx'', ''ICCA_TEMPLATE.docx'') as report_type',
',       adt.code || ''.'' || cnt.company_name || ''.'' || clt.name                                       as report_name   ',
',       case ',
'            when adt.audit_completed = ''Y'' ',
'                and (select count(1) from icca_adt_forms fom where fom.adt_id = adt.id) > 0',
'                    then ''<i class="fa fa-forms"></i>'' ',
'            else ''<span class="disabled-icon" title="Audit nog niet voltooid."><i class="fa fa-forms"></i></span>''',
'        end audit_forms',
',       case ',
'            when adt.audit_completed = ''Y'' ',
'                and (select count(1) from icca_adt_forms fom where fom.adt_id = adt.id) > 0',
'                    then ''<i class="fa fa-bar-chart"></i>'' ',
'            else ''<span class="disabled-icon" title="Audit nog niet voltooid."><i class="fa fa-bar-chart"></i></span>''',
'        end audit_report',
',       case ',
'            when adt.audit_completed = ''Y'' ',
'                and (select count(1) from icca_adt_forms fom where fom.adt_id = adt.id) > 0',
'                    then ''<i class="fa fa-send-o"></i>'' ',
'            else ''<span class="disabled-icon" title="Audit nog niet voltooid."><i class="fa fa-send-o"></i></span>''',
'        end audit_report_vesturen',
'from    icca_audits adt',
'join    icca_clients          cnt on adt.cnt_id = cnt.id',
'join    icca_client_locations clt on adt.cln_id = clt.id',
'where   adt.cnt_id = :P1000_ID'))
