wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(20498160790640898541)
,p_name=>'Master Records'
,p_static_id=>'master-records'
,p_template=>3372714138756020509
,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  x.id,',
'        null link_class,',
'        apex_page.get_url(',
'            p_items  => ''P1000_ID,P1000_USR_ID,P1000_CNT_LOGO_ID'',',
'            p_values => x.id||'',''||x.usr_id||'',''||x.logo_id',
'        ) link,',
'        null icon_class,',
'        null link_attr,',
'        null icon_color_class,',
'        case when nvl(:P1000_ID, 0) = x.id then ''is-active'' else null end list_class,',
'        substr(x.company_name, 1, 50) ||',
'            case when length(x.company_name) > 50 then ''...'' end list_title,',
'        ''Audits: '' || nvl((select count(1) from icca_audits a where a.cnt_id = x.id), 0) list_text,',
'        null list_badge',
'from    icca_clients x',
'join    icca_users u on u.id = x.usr_id',
'where   ( :P1000_SEARCH is null',
'          or upper(x.company_name) like ''%''||upper(:P1000_SEARCH)||''%''',
'          or upper(x.contact_person) like ''%''||upper(:P1000_SEARCH)||''%''',
'        )',
'and     x.usr_id not in (select u.id from icca_users u where u.deleted = ''Y'')',
'and (',
'        :P1000_SHOW_INACTIVE = ''N''',
'     or u.active = ''Y''',
'    )',
'and (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'     or (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_PERFORMERS''',
'        and exists (',
'            select 1',
'            from   icca_pfr_clients pnt',
'            join   icca_performers  pfr on pfr.id = pnt.pfr_id',
'            where  pnt.cnt_id = x.id',
'            and    pfr.usr_id = :F_GBR_ID',
'        )',
'     )',
'     or (',
'        /* <-- HIER je extra OR */',
'        /* voorbeeld: UGP_CLIENTS ziet alleen zijn eigen client */',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS''',
'        and x.usr_id = :F_GBR_ID',
'     )',
')',
'order by x.created_date, x.modified_date, x.company_name;',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P1000_SEARCH,P1000_SHOW_INACTIVE'
,p_lazy_loading=>false
,p_query_row_template=>2095080600153409441
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'<div class="u-tC">Geen gegevens gevonden.</div>'
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
