,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if (:F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS'')',
'    then',
'        return :F_CNT_ID;',
'    else',
'        return :P1001_CNT_ID;',
'    end if;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Klant'
,p_source=>'CNT_ID'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  cnt.company_name as d,',
'        cnt.id           as r',
'from    icca_clients cnt',
'join    icca_users   usr on usr.id = cnt.usr_id',
'where   usr.deleted = ''N''',
'and     usr.active  = ''Y''',
'and (',
'        -- Admin ziet alles',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'',
'     or (',
'        -- Performer ziet alleen gekoppelde clients',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_PERFORMERS''',
'        and exists (',
'            select 1',
'            from   icca_pfr_clients pnt',
'            join   icca_performers  pfr on pfr.id = pnt.pfr_id',
'            where  pnt.cnt_id = cnt.id',
'            and    pfr.usr_id = :F_GBR_ID',
'        )',
'     )',
'',
'     or (',
'        -- Client ziet alleen eigen client record',
'        :F_UGP_SYSTEEM_NAAM in (''UGP_CLIENTS'')',
'        and cnt.usr_id = :F_GBR_ID',
'        and cnt.id     = :F_CNT_ID',
'     )',
')',
'order by cnt.company_name;',
''))
,p_cSize=>30
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if (:F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS'')',
