,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign performers to audit'
,p_static_id=>'assign-performers-to-audit'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_adt_performers where adt_id = :P1001_ID;',
'    --',
'    for pfr in  (   select  trim(regexp_substr(:P1001_PERFORMERS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P1001_PERFORMERS, '':'')+1',
'    )',
'    loop',
'        insert into icca_adt_performers (adt_id, pfr_id)',
'            values (:P1001_ID, pfr.id)',
'            ;',
'    end loop;',
'    --',
'    update  icca_audits',
'    set     cnt_id = :P1001_CNT_ID',
'    where   id = :P1001_ID',
'    ;',
'    --',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
