wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(82613280437694790)
,p_plug_name=>'Formulieren'
,p_static_id=>'formulieren'
,p_parent_plug_id=>wwv_flow_imp.id(82765758239730596)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ''<span role="img" aria-label="Edit" class="fa fa-edit" title="Edit"></span>''    edit',
',       fom.id                                                                          id',
',       flr.name||''-''||ara.abbreviation||''.''||fom.area_number||''-''||cat.name            Formulier_omschrijving',
',       flr.name                                                                        verdieping',
',       ara.abbreviation                                                                ruimte_omschrijving    ',
',       fom.area_number                                                                 ruimte_nummer',
',       cat.name                                                                        categorie',
',       fom.element_count                                                               tel_elementen',
',       fom.remark                                                                      opmerking',
',       nvl((select sum(error_count) from icca_fom_errors where fom_id = fom.id), 0)    aantal_fouten',
',       case when nvl((select count(1) from icca_fom_errors where fom_id = fom.id), 0) > 0 ',
'                then q''[Fouten Bekijken]''',
'            else '''' end fouten_bekijken',
',       fom.created_date',
'from    icca_adt_forms  fom',
'join    icca_floors     flr on fom.flr_id = flr.id',
'join    icca_categories cat on fom.cat_id = cat.id',
'join    icca_areas      ara on fom.ara_id = ara.id',
'where   fom.adt_id = :P1002_AUDIT_ID',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1002_AUDIT_ID'
);
