,p_plug_name=>'KPI Onderwerpen'
,p_static_id=>'kpi-onderwerpen'
,p_parent_plug_id=>wwv_flow_imp.id(82766270338730602)
,p_region_template_options=>'#DEFAULT#:is-expanded:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  adt.id                  as adt_id',
',       ket.name                as naam_element',
',       ant.element_value       as status',
',       case ',
'            when ant.element_value = ''O'' then ''Onvoldoende''',
'            when ant.element_value = ''V'' then ''Voldoende''',
'            when ant.element_value = ''G'' then ''Goed''',
'            when ant.element_value = ''N'' then ''N.v.t.''',
'            else ant.element_value',
'        end                     as status_weergave',
',       ant.element_comment     as opmerkingen',
'from    icca_audits             adt',
'join    icca_adt_kpi_elements   ant on ant.adt_id = adt.id',
'join    icca_kpi_elementen      ket on ant.ket_id = ket.id',
'where   adt.id = :P1002_AUDIT_ID',
'and     ant.element_value is not null',
'order by ket.name',
';'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P1002_AUDIT_ID'
,p_ai_enabled=>false
);
