    '        ;',
    '    when ''U'' ',
    '    then',
    '        update  icca_fom_errors',
    '        set     ete_id                      = :ETE_ID',
    '        ,       epe_id                      = :EPE_ID',
    '        ,       error_count                 = :ERROR_COUNT',
    '        ,       log_book_remark             = :LOG_BOOK_REMARK',
    '        ,       technical_aspects_remark    = :TECHNICAL_ASPECTS_REMARK',
    '        where   id  = :ID;',
    '    when ''D'' ',
    '    then',
    '        delete icca_fom_errors         where id  = :ID;',
    '    end case;',
