'            join   icca_performers  pfr on pfr.id = pnt.pfr_id',
'            where  pnt.cnt_id = cnt.id',
'            and    pfr.usr_id = :F_GBR_ID',
'        )',
'     )',
'',
'     or (',
'        -- Client ziet alleen eigen client record',
'        :F_UGP_SYSTEEM_NAAM in (''UGP_CLIENTS'')',
'        and cnt.usr_id = :F_GBR_ID',
'        and cnt.id     = :F_CNT_ID',
'     )',
')',
'order by cnt.company_name;',
''))
,p_cSize=>30
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
