wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34198975151448639)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Bulk Insert Audits'
,p_static_id=>'bulk-insert-audits'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_locations   apex_t_varchar2;',
'    l_performers  apex_t_varchar2;',
'    l_adt_id      icca_audits.id%type;',
'begin',
'    -- Split locaties (multi-select)',
'    l_locations := apex_string.split(p_str => :P1005_CLN_ID, p_sep => '':'');',
'',
'    if l_locations.count = 0 then',
'        raise_application_error(-20001, ''Selecteer minimaal 1 locatie.'');',
'    end if;',
'',
'    -- Split performers (multi-select)',
'    -- (als performers leeg mogen zijn, dan geen error; we checken straks count)',
'    l_performers := apex_string.split(p_str => :P1005_PERFORMERS, p_sep => '':'');',
'',
'    -- Per locatie: insert audit + insert performers',
'    for i in 1 .. l_locations.count loop',
'',
'        -- 1) Insert audit record (pfr_id leeg, id leeg)',
'        insert into icca_audits (',
'            cnt_id,',
'            cln_id,',
'            type,',
'            audit_date,',
'            active,',
'            activate,',
'            audit_completed',
'        ) values (',
'            :P1005_CNT_ID,',
'            to_number(l_locations(i)),',
'            :P1005_TYPE,',
'            :P1005_AUDIT_DATE,',
'            :P1005_ACTIVE,',
'            :P1005_ACTIVATE,',
'            :P1005_AUDIT_COMPLETED',
'        )',
'        returning id into l_adt_id;',
'',
'        -- 2) Performers koppelen aan deze nieuwe audit',
'        if l_performers.count > 0 then',
'            for j in 1 .. l_performers.count loop',
'                insert into icca_adt_performers (adt_id, pfr_id)',
'                values (l_adt_id, to_number(l_performers(j)));',
'            end loop;',
'        end if;',
'',
'    end loop;',
'',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(45970059752153906)
,p_internal_uid=>34198975151448639
);
