,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'    l_queue_id   number;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :P1011_JSON_FILE,',
'                        p_sep => '':'' );',
'    ',
'    --',
'    for i in 1 .. l_file_names.count ',
'    loop',
'        select  *',
'        into    l_file',
'        from    apex_application_temp_files',
'        where   name = l_file_names(i);',
'',
'        apex_debug.message(''l_file.filename => '' || l_file.FILENAME);',
'        --',
'        icca_audit_file_upload.p_submit_upload(',
'            p_file_blob => l_file.blob_content',
'        ,   p_filename  => l_file.FILENAME',
'        ,   p_cnt_id    => :P1011_CNT_ID',
'        ,   po_queue_id => l_queue_id',
'        );',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P1011_JSON_FILE is not null'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_process_success_message=>unistr('Auditgegevens succesvol ge\00EFmporteerd.')
,p_internal_uid=>17227258179924140
