wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(83711349824241196)
,p_event_id=>wwv_flow_imp.id(83306706706301976)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code-2'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var adt_id = this.triggeringElement.dataset.id;',
    '',
    '// First: capture the first image (#container)',
    'html2canvas(document.querySelector("#container"), { scale: 1, useCORS: true }).then(canvas1 => {',
    '  var base64_1 = canvas1.toDataURL("image/jpeg").split('','')[1];',
    '',
    '  // INSERT with first image',
    '  apex.server.process("SAVE_IMAGE_INSERT", {',
    '    p_clob_01: base64_1,',
    '    x01: adt_id',
    '  }, {',
    '    success: function (data) {',
    '      console.log("First image inserted:", data);',
    '',
    '      // Now capture the second image (#hoofd)',
    '      html2canvas(document.querySelector("#hoofd"), { scale: 1, useCORS: true }).then(canvas2 => {',
    '        var base64_2 = canvas2.toDataURL("image/jpeg").split('','')[1];',
    '',
    '        // UPDATE with second image',
    '        apex.server.process("SAVE_IMAGE_UPDATE", {',
    '          p_clob_01: base64_2,',
    '          x01: adt_id',
    '        }, {',
    '          success: function (data) {',
    '            console.log("Second image updated:", data);',
    '            apex.navigation.redirect("f?p=&APP_ID.:3055:&APP_SESSION.::&DEBUG.::::");',
    '          },',
    '          error: function (err) {',
    '            console.error("Error updating image_2:", err);',
    '            alert("Image 1 saved but failed to update image 2.");',
    '          }',
    '        });',
    '',
    '      }).catch(err => {',
    '        console.error("Failed to capture #hoofd:", err);',
    '        alert("Image 1 saved, but failed to capture second image.");',
    '      });',
    '    },',
    '    error: function (err) {',
    '      console.error("Error inserting image 1:", err);',
    '      alert("Failed to save first image.");',
    '    }',
    '  });',
    '',
    '}).catch(err => {',
    '  console.error("Failed to capture #container:", err);',
    '  alert("Failed to capture first image.");',
    '});',
    '')))).to_clob
,p_da_action_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'html2canvas(document.querySelector("#container"), { scale: 1, useCORS: true }).then(canvas => {',
'    var base64data = canvas.toDataURL("image/jpeg").split('','')[1]; ',
'',
'    console.log(base64data);',
'',
'    var adt_id = this.triggeringElement.dataset.id;',
'    console.log("adt_id uit data-id:", adt_id);',
'    ',
'    // Call SAVE_IMAGE only',
'    apex.server.process("SAVE_IMAGE", {',
'        p_clob_01: base64data,',
'        x01: adt_id',
'    }, {',
'        success: function(data) {',
'            console.log("SAVE_IMAGE success:", data);',
'',
'            // Redirect after a short delay',
'            setTimeout(function() {',
'                 apex.navigation.redirect("f?p=&APP_ID.:3055:&APP_SESSION.::&DEBUG.::::");',
'            }, 200);',
'        },',
'        error: function(err) {',
'            console.error("Error in SAVE_IMAGE:", err);',
'        }',
'    });',
'',
'});',
''))
);
end;
