wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(81729403460873381)
,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'PLUGIN_BE.APEXRND.AOP'
,p_process_name=>'Toon Rapport'
,p_static_id=>'toon-rapport'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_03', '&P3065_REPORT_NAME.',
  'attribute_04', 'pdf',
  'attribute_05', 'SQL',
  'attribute_06', 'APEX',
  'attribute_07', '&P3065_REPORT_TYPE.',
  'attribute_11', wwv_flow_string.join(wwv_flow_t_varchar2(
    'with w_data as (',
    '    select  aop_data',
    '    ,       doc_ids',
    '    from icca_aop_report_data_vw',
    '    where adt_id = :P3065_ADT_ID',
    ')',
    ', w_all as(',
    '    select  aop_data',
    '    ,       doc_ids',
    '    from    w_data',
    '    /*',
    '        Fallback query so report does not throw an AOP error, report will instead be empty',
    '        COMMENTING OUT AS IT DOESNT WORK, FOR WHATEVER REASON',
    '    */',
    '    -- union all',
    '    -- select  to_clob(''',
    '    -- [',
    '    --     {',
    '    --         "filename": "rapport",',
    '    --         "data": []',
    '    --     }',
    '    -- ]'') aop_data',
    '    -- ,       null doc_ids',
    '    -- from    dual',
    '    -- where   not exists(',
    '    --     select  1',
    '    --     from    w_data-- ',
    '    -- )',
    ')',
    '/*',
    '   Performance issues if BLOBS directly in view since would need to convert every image to base64 as well',
    '   This is probably faster',
    '*/',
    'select  case when doc_ids is not null then json_transform (',
    '                aop_data',
    '            ,   set ''$.data[0].htmlContent'' =  icca_aop_pdf.f_get_imgs_html(doc_ids)',
    '                returning clob',
    '        ) else aop_data end as aop_data',
    'from    w_all',
    ';',
    '')),
  'attribute_14', 'PROCEDURE',
  'attribute_15', 'icca_aop_pdf.show_inline_pdf')).to_clob
,p_required_patch=>wwv_flow_imp.id(20494685522089407564)
,p_internal_uid=>32335341263465018
,p_process_comment=>'show_pdf'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14187159820940602)
,p_process_sequence=>40
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Toon Rapport AOP Call'
,p_static_id=>'toon-rapport-aop-call'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_return blob;',
'    l_output varchar2(1000);',
'    l_log_id number;',
'',
'    l_query varchar2(1000):= q''[',
'                with w_data as (',
'                select  aop_data',
'                ,       doc_log_book_ids',
'                ,       doc_tech_aspects_ids',
'                ,       audit_report_type',
'                from    icca_aop_report_data_vw',
'                where   adt_id =  :P_ADT_ID',
'            )',
'            select case when doc_log_book_ids is not null or doc_tech_aspects_ids is not null then json_transform (',
'                            aop_data',
'            ,   set ''$.data[0].htmlContent'' =  icca_aop_pdf.f_main_get_images(p_doc_log_book_ids => doc_log_book_ids, p_doc_tech_aspects_ids => doc_tech_aspects_ids)',
'                            returning clob',
'                    ) else aop_data end as aop_data',
'            from    w_data',
'    ]''',
'        ;',
'        l_binds             wwv_flow_plugin_util.t_bind_list;',
'',
'        -- ,   set ''$.data[0].htmlContent'' =  icca_aop_pdf.f_main_get_images(p_doc_log_book_ids => 5401, p_doc_tech_aspects_ids => 5401, p_duplicate_number => 24, p_duplicate_tech => 24)',
'        -- ,   set ''$.data[0].htmlContent'' =  icca_aop_pdf.f_main_get_images(p_doc_log_book_ids => doc_log_book_ids, p_doc_tech_aspects_ids => doc_tech_aspects_ids)',
'begin ',
'    aop_api_pkg.g_debug := null;',
'    -- aop_api_pkg.g_debug := ''Local'';',
'',
'    l_binds(1).name  := ''P_ADT_ID'';',
'    l_binds(1).value := :P3065_ADT_ID;',
'',
'',
'',
'    l_return := aop_api_pkg.plsql_call_to_aop (',
'        p_data_type => aop_api_pkg.c_source_type_sql',
'    ,   p_data_source => l_query',
'    ,   p_template_type => aop_api_pkg.c_source_type_apex',
'    ,   p_template_source => :P3065_REPORT_TYPE',
'    ,   p_app_id => 100',
'    ,   p_output_type => ''pdf''',
'    ,   p_output_filename => :P3065_REPORT_NAME',
'    ,   p_aop_url => ''https://api.apexofficeprint.com/''',
'    ,   p_api_key => ''361ACD26CA57F476E0637203000ACB44''',
'    ,   p_binds   => l_binds',
'    ,   p_aop_mode => ''development''',
'     --,   p_aop_mode => ''production''',
'    ',
'    );',
'',
'        sys.htp.init;',
