',       adm.first_name',
',       adm.last_name',
',       nvl((   select  listagg(eml.email, ''<br>'') within group (order by eml.email)',
'            from    icca_usr_emails eml',
'            where   eml.usr_id = adm.usr_id',
'            group by eml.usr_id',
'        ), usr.email ) email',
',       usr.active',
',       ''<span class="action-icon" alt="Nieuw Wachtwoord Emailen"><i class="fa fa-key"></i> Nieuw Wachtwoord Emailen</span>'' send_reset_password',
',       adm.created_date',
',       adm.created_by',
',       adm.modified_date',
',       adm.modified_by',
'from    icca_administrators adm',
'join    icca_users          usr on usr.id = adm.usr_id',
'where   usr.deleted = ''N''',
'order by created_date desc'))
