'select  pfr.id',
',       pfr.usr_id',
',       initcap(usr.username) username',
',       usr.active',
',       nvl((   select  listagg(eml.email, ''<br>'') within group (order by eml.email)',
'            from    icca_usr_emails eml',
'            where   eml.usr_id = pfr.usr_id',
'            group by eml.usr_id',
'        ), usr.email ) email',
',       pfr.first_name',
',       ''<span class="action-icon" alt="Nieuw Wachtwoord Emailen"><i class="fa fa-key"></i> Nieuw Wachtwoord Emailen</span>'' send_reset_password',
',       pfr.last_name',
',       pfr.phone_number',
',       pfr.mobile_number',
',       pfr.is_auditor',
',       pfr.is_project_leader',
',       (select count(1) from icca_pfr_clients where pfr_id = pfr.id) aantal_klanten',
',       pfr.created_date',
',       pfr.created_by',
',       pfr.modified_date',
',       pfr.modified_by',
'from    icca_performers pfr',
'join    icca_users      usr on usr.id = pfr.usr_Id',
'where   usr.deleted = ''N''',
'and (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'     or (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS''',
'        and exists (',
'            select 1',
'            from   icca_pfr_clients pnt',
'            where  pnt.pfr_id = pfr.id',
'            and    pnt.cnt_id in (',
'                select c.id',
'                from   icca_clients c',
'                where  c.usr_id = :F_GBR_ID',
'            )',
'        )',
'     )',
')',
'order by pfr.created_date desc'))
