,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  cnt_id',
'from    icca_pfr_clients d',
'join    icca_clients cnt on cnt.id = d.cnt_id',
'where   pfr_id = :P8008_ID',
'order by cnt.company_name'))
,p_source_type=>'QUERY_COLON'
,p_display_as=>'NATIVE_SHUTTLE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  cnt.company_name',
',       cnt.id',
'from    icca_clients  cnt',
'join    icca_users    usr on usr.id = cnt.usr_id',
'where   usr.deleted = ''N''',
'and     usr.active = ''Y''',
'and (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'     or (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS''',
'        and cnt.usr_id = :F_GBR_ID',
'     )',
')',
'order by cnt.company_name;'))
,p_cHeight=>30
,p_field_template=>1610598484065263269
,p_item_template_options=>'#DEFAULT#'
