,p_process_name=>'Assign Clients to performers'
,p_static_id=>'assign-clients-to-performers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_pfr_clients where pfr_id = :P8008_ID;',
'    --',
'    for cnt in  (   select  trim(regexp_substr(:P8008_CLIENTS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8008_CLIENTS, '':'')+1',
'    )',
'    loop',
'        insert into icca_pfr_clients (pfr_id, cnt_id)',
'            values (:P8008_ID, cnt.id)',
'            ;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
