wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13191973709900343)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process User emails'
,p_static_id=>'process-user-emails'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_email  varchar2(100);',
'begin',
'    apex_debug.message(''ik ga af'');',
'    -- 1. Insert / update (merge)',
'    for v in (  select trim(regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level)) as email',
'                from dual',
'                connect by regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level) is not null',
'            )',
'    loop',
'        v_email := v.email;',
'',
'        merge into icca_usr_emails tgt',
'            using (select :P8008_ID_1 as usr_id, v_email as email from dual) src',
'            on (tgt.usr_id = src.usr_id and tgt.email = src.email)',
'        when matched then',
'          update set modified_date = sysdate, modified_by = :APP_USER',
'        when not matched then',
'          insert (usr_id, email, created_date, created_by)',
'          values (src.usr_id, src.email, sysdate, :APP_USER);',
'    end loop;',
'',
'    -- 2. Delete e-mails die niet meer in :P8008_EMAIL voorkomen',
'    delete from icca_usr_emails',
'    where usr_id = :P8008_ID_1',
'    and email not in (',
'      select trim(regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level))',
'      from dual',
'      connect by regexp_substr(:P8008_EMAIL, ''[^,]+'', 1, level) is not null',
'    );',
'',
'    commit;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>13191973709900343
);
