wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20499376825631355584)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set user password'
,p_static_id=>'set-user-password'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    cursor c_get_usr_password',
'    is',
'        select  password',
'        from    icca_users usr',
'        where   id = :P8008_ID_1',
'        ;',
'    --',
'    lv_usr_password icca_users.password%type;',
'    --        ',
'begin',
'    --',
'    open    c_get_usr_password;',
'    fetch   c_get_usr_password',
'    into    lv_usr_password;',
'    close   c_get_usr_password;',
'    --',
'    if (    lv_usr_password is not null',
'        and :P8008_PASSWORD is null',
'    )',
'    then',
'        :P8008_PASSWORD := lv_usr_password;',
'    else',
'        :P8008_PASSWORD_UNHASHED := :P8008_PASSWORD; -- Set unhashed pwd so that we can use it to send mails.',
'        :P8008_PASSWORD          := icca_authentication.f_get_hash( pi_password => :P8008_PASSWORD );        ',
'    end if;',
'    --',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
