,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Categories to areas'
,p_static_id=>'assign-categories-to-areas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_ara_categories where ara_id = :P8013_ID;',
'    --',
'    for cat in  (   select  trim(regexp_substr(:P8013_CATEGORIES, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8013_CATEGORIES, '':'')+1',
'    )',
'    loop',
'        insert into icca_ara_categories (ara_id, cat_id)',
'            values (:P8013_ID, cat.id)',
'            ;',
'    end loop;',
'    --',
'    update  icca_areas',
'    set     name = :P8013_NAME',
'    where   id = :P8013_ID',
'    ;',
'    --',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
