 p_id=>wwv_flow_imp.id(20496955844327419731)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Areas to elementtypen'
,p_static_id=>'assign-areas-to-elementtypen'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    --',
'    delete from icca_epe_areas where epe_id = :P8020_ID;',
'    --',
'    for ara in  (   select  trim(regexp_substr(:P8020_AREAS, ''[^:]+'', 1, level)) id',
'                    from    dual',
'                    connect by level <= regexp_count(:P8020_AREAS, '':'')+1',
'    )',
'    loop',
'        insert into icca_epe_areas (epe_id, ara_id)',
'            values (:P8020_ID, ara.id)',
'            ;',
'    end loop;',
'    --',
'    update  icca_elementtypes',
'    set     name = :P8020_NAME',
'    where   id = :P8020_ID',
'    ;',
'    --',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Elementtype gegevens succesvol verwerkt.'
,p_internal_uid=>7397823854330823
);
