,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select x."ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P8021_ID'', p_values => x."ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P8021_ID,''0'') = x."ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr(x."COMPANY_NAME", 1, 50)||( case when length(x."COMPANY_NAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    ''Locaties: '' || (nvl((select count(1) from icca_client_locations where cnt_id = x.id), 0)) LIST_TEXT,',
'    null LIST_BADGE',
'from "ICCA_CLIENTS" x',
'join icca_users u on u.id = x.usr_id',
'where (:P8021_SEARCH is null',
'        or upper(x."COMPANY_NAME") like ''%''||upper(:P8021_SEARCH)||''%''',
'        or upper(x."CONTACT_PERSON") like ''%''||upper(:P8021_SEARCH)||''%''',
'    )',
'and x.usr_id not in (select id from icca_users where deleted = ''Y'')',
'and (',
'        :P8021_SHOW_INACTIVE = ''N''',
'     or u.active = ''Y''',
'    )',
'order by x.created_date desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P8021_SEARCH,P8021_SHOW_INACTIVE'
,p_lazy_loading=>false
