,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ket.id,',
'        ket.name,',
'        ket.active,',
'        (select count(1)',
'         from   icca_ket_clients kcn',
'         where  kcn.ket_id = ket.id) as aantal_klanten,',
'        ket.created_date,',
'        ket.created_by,',
'        ket.modified_date,',
'        ket.modified_by',
'from    icca_kpi_elementen ket',
'where',
'    (',
'        :F_UGP_SYSTEEM_NAAM = ''UGP_ADMIN''',
'        or',
'        (',
'            :F_UGP_SYSTEEM_NAAM = ''UGP_CLIENTS''',
'            and exists (',
'                select 1',
'                from   icca_ket_clients kcn',
'                where  kcn.ket_id = ket.id',
'                and    kcn.cnt_id in (',
'                    select c.id',
'                    from   icca_clients c',
'                    where  c.usr_id = :F_GBR_ID',
'                )',
'            )',
'        )',
'    )',
'order by ket.created_date desc;',
''))
,p_plug_source_type=>'NATIVE_IR'
