wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(86972509176619316)
,p_process_sequence=>140
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process User emails'
,p_static_id=>'process-user-emails'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_email  varchar2(100);',
'begin',
'    -- 1. Insert / update (merge)',
'    for v in (  select trim(regexp_substr(:P8025_EMAIL, ''[^,]+'', 1, level)) as email',
'                from dual',
'                connect by regexp_substr(:P8025_EMAIL, ''[^,]+'', 1, level) is not null',
'            )',
'    loop',
'        v_email := v.email;',
'',
'        merge into icca_usr_emails tgt',
'            using (select :P8025_USR_FORM_ID as usr_id, v_email as email from dual) src',
'            on (tgt.usr_id = src.usr_id and tgt.email = src.email)',
'        when matched then',
'          update set modified_date = sysdate, modified_by = :APP_USER',
'        when not matched then',
'          insert (usr_id, email, created_date, created_by)',
'          values (src.usr_id, src.email, sysdate, :APP_USER);',
'    end loop;',
'',
'    -- 2. Delete e-mails die niet meer in :P8025_EMAIL voorkomen',
'    delete from icca_usr_emails',
'    where usr_id = :P8025_USR_FORM_ID',
'    and email not in (',
'      select trim(regexp_substr(:P8025_EMAIL, ''[^,]+'', 1, level))',
