,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update/delete - Upload logo'
,p_static_id=>'update-delete-upload-logo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob          blob;',
'    l_filename      varchar2(500);',
'    l_mime_type     varchar2(100);',
'    l_doc_id        number;',
'    l_changed       varchar2(10);',
'    l_file_names    apex_t_varchar2;',
'    l_file          apex_application_temp_files%rowtype;',
'    ln_doc_id       icca_documents.id%type;    ',
'begin',
'    l_changed := :P8025_LOGO_CHANGED;',
'    ',
'    if l_changed = ''DELETE'' then',
'        -- Verwijder logo',
'        :P8025_LOGO_ID := null;',
'    end if;',
'',
'    if :P8025_LOGO_FILE is not null',
'    then',
'        l_file_names := apex_string.split (',
'                            p_str => :P8025_LOGO_FILE,',
'                            p_sep => '':'' );',
'        ',
'        --',
'        for i in 1 .. l_file_names.count ',
'        loop',
'            select  *',
'            into    l_file',
'            from    apex_application_temp_files',
'            where   name = l_file_names(i);',
'',
'            apex_debug.message(''l_file.filename => '' || l_file.FILENAME);',
'',
'            -- add code here to store the uploaded file in your own table',
'            ln_doc_id := icca_file_upload.f_save_and_register_document(     p_blob          => l_file.blob_content',
'                                                                        ,   p_filename      => l_file.filename',
'                                                                        ,   p_mime_type     => l_file.mime_type',
'                                                                        ,   p_document_name => l_file.filename',
'                                                                        );',
'            :P8025_LOGO_ID := ln_doc_id;                                                                    ',
'        end loop;',
'    end if;',
'    ',
'    -- Reset flag',
'    :P8025_LOGO_CHANGED := null;',
'    ',
'    commit;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(86957408880619239)
,p_internal_uid=>15966808305031611
);
end;
